package ro.whistlab.coach;import java.util.*;/** Test adapter keeps internal enumeration out of the player public API. */public final class WorldEnumerationProbe {public record Proof(int card,boolean certified,int worlds,int nodes){}public static Proof certificate(IndependentPlayer.Position p,int selected,int limit){var result=ContractGuarantee.choose(p,selected,limit);return new Proof(result.card(),result.certified(),result.worlds(),result.nodes());}private WorldEnumerationProbe(){}public static List<List<List<Integer>>> enumerate(IndependentPlayer.Position p){return IndependentPlayer.smallDeals(p);}}
